INSERT INTO _migration_436_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_genetics_s1_001', 'topic_alevel_bio_genetics', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'What term describes the different versions of a gene found at the same locus on homologous chromosomes?', 'multiple_choice', NULL, '["A. Chromatids","B. Codons","C. Operons","D. Alleles"]', 'D', 'Alleles are alternative forms of a gene occupying the same locus on homologous chromosomes, such as the T and t alleles for height in pea plants. Chromatids are the copies of a replicated chromosome, codons are triplets of mRNA bases, and operons are clusters of prokaryotic genes. Therefore the correct answer is D: Alleles.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_genetics_s1_002', 'topic_alevel_bio_genetics', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In a DNA molecule, which base always pairs with adenine?', 'multiple_choice', NULL, '["A. Thymine","B. Guanine","C. Cytosine","D. Uracil"]', 'A', 'In double-stranded DNA, adenine forms two hydrogen bonds with thymine, while guanine forms three hydrogen bonds with cytosine; this complementary base pairing underlies semi-conservative replication. Uracil replaces thymine in RNA and does not occur in DNA. Therefore the correct answer is A: Thymine.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_genetics_s1_003', 'topic_alevel_bio_genetics', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Two heterozygous tall pea plants (Tt × Tt) are crossed. What proportion of the offspring are expected to be short?', 'multiple_choice', NULL, '["A. 1/2","B. 1/4","C. 3/4","D. All of them"]', 'B', 'A Punnett square for Tt × Tt gives genotypes 1 TT : 2 Tt : 1 tt. Because the tall allele T is dominant, only the homozygous recessive tt genotype expresses the short phenotype, so one in four offspring (25%) is expected to be short. Therefore the correct answer is B: 1/4.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_genetics_s1_004', 'topic_alevel_bio_genetics', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which statement correctly contrasts transcription and translation?', 'multiple_choice', NULL, '["A. Transcription occurs at ribosomes; translation occurs in the nucleus","B. Both processes produce identical copies of the DNA molecule","C. Transcription synthesises mRNA from a DNA template in the nucleus; translation assembles a polypeptide at a ribosome","D. Translation synthesises mRNA; transcription joins amino acids together"]', 'C', 'Transcription uses RNA polymerase to build a complementary mRNA copy of a gene in the nucleus. Translation then reads that mRNA codon by codon at ribosomes in the cytoplasm, where transfer RNAs deliver amino acids that are joined by peptide bonds into a polypeptide. Therefore the correct answer is C: Transcription synthesises mRNA from a DNA template in the nucleus; translation assembles a polypeptide at a ribosome.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_genetics_s1_005', 'topic_alevel_bio_genetics', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In a population in Hardy–Weinberg equilibrium, the frequency of the dominant allele A is 0.6. What proportion of the population is expected to be heterozygous?', 'multiple_choice', NULL, '["A. 36%","B. 24%","C. 16%","D. 48%"]', 'D', 'The allele frequency p = 0.6, so q = 1 − p = 0.4. The heterozygote frequency is 2pq = 2 × 0.6 × 0.4 = 0.48, so 48% of the population are heterozygous; the homozygous genotypes are p² = 36% (AA) and q² = 16% (aa). Therefore the correct answer is D: 48%.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_cambridge'),
('q_albio_genetics_s1_006', 'topic_alevel_bio_genetics', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student studies how a gene is expressed as a polypeptide and how mutations can affect it.', 'structured', NULL, NULL, '(a) mRNA carries a complementary copy of the base sequence of a gene from the DNA in the nucleus to a ribosome in the cytoplasm; its sequence of codons is then read during translation to determine the order of amino acids in the polypeptide. (b) Each tRNA molecule carries a specific amino acid and has an anticodon complementary to an mRNA codon; tRNAs bind to the ribosome in sequence so that their amino acids are joined by peptide bonds in the order specified by the mRNA. (c) The genetic code is degenerate: most amino acids are coded for by more than one codon, so a substitution can produce a different codon that still specifies the same amino acid (a silent mutation), leaving the polypeptide sequence unchanged.', '(a) mRNA carries a complementary copy of the base sequence of a gene from the DNA in the nucleus to a ribosome in the cytoplasm; its sequence of codons is then read during translation to determine the order of amino acids in the polypeptide. (b) Each tRNA molecule carries a specific amino acid and has an anticodon complementary to an mRNA codon; tRNAs bind to the ribosome in sequence so that their amino acids are joined by peptide bonds in the order specified by the mRNA. (c) The genetic code is degenerate: most amino acids are coded for by more than one codon, so a substitution can produce a different codon that still specifies the same amino acid (a silent mutation), leaving the polypeptide sequence unchanged.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_436_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_albio_genetics_s1_006_a', 'q_albio_genetics_s1_006', 'a', 'Outline the role of messenger RNA (mRNA) in protein synthesis.', '2', 'mRNA carries a complementary copy of the base sequence of a gene from the DNA in the nucleus to a ribosome in the cytoplasm; its sequence of codons is then read during translation to determine the order of amino acids in the polypeptide.', '1'),
('sqp_q_albio_genetics_s1_006_b', 'q_albio_genetics_s1_006', 'b', 'Describe the role of transfer RNA (tRNA) during translation.', '2', 'Each tRNA molecule carries a specific amino acid and has an anticodon complementary to an mRNA codon; tRNAs bind to the ribosome in sequence so that their amino acids are joined by peptide bonds in the order specified by the mRNA.', '2'),
('sqp_q_albio_genetics_s1_006_c', 'q_albio_genetics_s1_006', 'c', 'Explain why a base substitution mutation in a gene does not always change the amino acid sequence of the polypeptide.', '2', 'The genetic code is degenerate: most amino acids are coded for by more than one codon, so a substitution can produce a different codon that still specifies the same amino acid (a silent mutation), leaving the polypeptide sequence unchanged.', '3');
INSERT INTO _migration_436_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_436_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_436_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_436_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_436_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_436_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint1-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_436_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_436_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_436_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_436_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_436_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_436_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
